// Offline support: keeps a copy of the app's files on the device so it works
// with no connection (e.g. from the home screen at the pool).
//
// The block below is generated by tools/update-sw.py from the files' contents.
// Run that script after changing any app file, so devices pick up the update.

// BEGIN GENERATED
const VERSION = 'b75ce3e8a57d';
const FILES = [
  './',
  'css/style.css',
  'icon.svg',
  'icons/apple-touch-icon.png',
  'icons/icon-192.png',
  'icons/icon-512.png',
  'index.html',
  'js/animate-mode.js',
  'js/animation.js',
  'js/input.js',
  'js/library.js',
  'js/lines.js',
  'js/main.js',
  'js/pieces.js',
  'js/pitch.js',
  'js/state.js',
  'js/storage.js',
  'js/svg.js',
  'js/ui.js',
  'manifest.webmanifest',
];
// END GENERATED

const CACHE = `cpt-${VERSION}`;

// Download every file into a new cache. addAll is all-or-nothing, so a device
// never ends up with a mix of old and new files.
self.addEventListener('install', (event) => {
  event.waitUntil(
    caches
      .open(CACHE)
      .then((cache) => cache.addAll(FILES.map((f) => new Request(f, { cache: 'reload' }))))
      .then(() => self.skipWaiting()),
  );
});

// Drop caches from older versions.
self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) => Promise.all(keys.filter((k) => k.startsWith('cpt-') && k !== CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim()),
  );
});

// Serve from the cache first; fall back to the network for anything else.
self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET' || new URL(req.url).origin !== self.location.origin) return;
  event.respondWith(
    caches.match(req, { ignoreSearch: true }).then(
      (hit) =>
        hit ||
        fetch(req).catch(() => (req.mode === 'navigate' ? caches.match('./') : Response.error())),
    ),
  );
});
